"""Sort semantic version strings by SemVer 2.0.0 precedence."""


def _parse(version):
    """Return (core_parts, prerelease_or_None). Build metadata is discarded."""
    base = version.split('+', 1)[0]
    if '-' in base:
        core, pre = base.split('-', 1)
    else:
        core, pre = base, None
    parts = tuple(int(x) for x in core.split('.'))
    return parts, pre


def _precedence_key(version):
    core, pre = _parse(version)
    if pre is None:
        # A release version ranks above any pre-release of the same core.
        pre_key = (1,)
    else:
        ids = []
        for ident in pre.split('.'):
            if ident.isdigit():
                # Numeric identifiers: compare as integers, lower than alphanumeric.
                ids.append((0, int(ident), ''))
            else:
                # Alphanumeric identifiers: ASCII order.
                ids.append((1, 0, ident))
        # Tuple comparison gives left-to-right order and shorter-is-lower on prefix ties.
        pre_key = (0, tuple(ids))
    return core + (pre_key,)


def sort_versions(vs):
    """Return the versions sorted lowest precedence first.

    Versions that compare equal (differing only in build metadata) keep
    their input order, since sorted() is stable.
    """
    return sorted(vs, key=_precedence_key)
